import json, sys

def get_text(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict):
                if c.get('type') == 'text':
                    parts.append(c.get('text',''))
                elif c.get('type') == 'tool_use':
                    parts.append(f"[TOOL_USE {c.get('name')} input={json.dumps(c.get('input'))[:300]}]")
                elif c.get('type') == 'tool_result':
                    cont = c.get('content')
                    if isinstance(cont, list):
                        cont = ' '.join(x.get('text','') if isinstance(x,dict) else str(x) for x in cont)
                    parts.append(f"[TOOL_RESULT {str(cont)[:300]}]")
            else:
                parts.append(str(c))
        return '\n'.join(parts)
    return str(content)

fn = sys.argv[1]
with open(fn) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        t = d.get('type')
        ts = d.get('timestamp','')
        if t == 'queue-operation':
            print(f"{ts} QUEUE[{d.get('operation')}]: {d.get('content','')[:400]}")
            continue
        msg = d.get('message')
        if msg:
            role = msg.get('role')
            text = get_text(msg.get('content'))
            usage = msg.get('usage')
            print(f"{ts} {t}/{role}: {text[:500]}")
        else:
            attach = d.get('attachment')
            if attach:
                print(f"{ts} {t} ATTACHMENT: {json.dumps(attach)[:300]}")
            else:
                print(f"{ts} {t}: {json.dumps(d)[:300]}")

